// DEV_RIO_701 アフィリエイト【下書き準備のみ・dry-run】。
// DEV_RIO_103 の出力を受け取る。★実リンク生成・自動埋め込み・公開はしない。偽URLは作らない。
// qa_status が無い手動テスト時は 'PASS' 扱い。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id ?? 'ca-aff-001',
  theme: i.theme ?? '（テーマ未設定）',
  note_body: i.note_body ?? i.note_draft_body ?? '',
  qa_status: i.qa_status ?? 'PASS',
  platform: 'note',
  action_type: 'prepare_affiliate_suggestions'
} }];

// アフィリ挿入案の生成プロンプトを Anthropic body オブジェクトとして組み立てる。
const i = $input.first().json;
const excerpt = String(i.note_body || '').slice(0, 600);
const prompt = `以下の記事に自然に差し込めるアフィリエイト商品の提案を最大3件。

テーマ: ${i.theme}
本文抜粋: ${excerpt}

各項目:
- genre: 商品ジャンル(book/tool/service 等)
- placement: 記事内の挿入位置の説明
- anchor: 20字以内のアンカー文

注意: 実在を断定しない。特定の商品名・URLは書かない。
出力は次のJSON配列のみ（前後に説明・コードブロック記号を付けない）:
[{"genre":"string","placement":"string","anchor":"string"}]`;
const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 1024,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, anthropic_body } }];

// Claude応答をパース。各提案に『リンク差し込み欄(プレースホルダ)』を付与して停止。捏造しない。
const input = $input.first().json;
const ctx = $('Collect Inputs').first().json;
let suggestions = [];
let parse_error = null;
if (input.error) {
  parse_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    const match = cleaned.match(/\[[\s\S]*\]/);
    suggestions = JSON.parse(match ? match[0] : cleaned);
    if (!Array.isArray(suggestions) || suggestions.length === 0) throw new Error('suggestions missing/empty');
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
}
if (parse_error) suggestions = [{ genre: 'manual', placement: '', anchor: '（AI応答の取得/解析に失敗。手動で作成してください）' }];
const enriched = suggestions.map((s, idx) => ({
  genre: s.genre ?? '', placement: s.placement ?? '', anchor: s.anchor ?? '',
  affiliate_link_placeholder: `<<ここに自分の楽天/AmazonアフィリID付きリンクを貼る #${idx + 1}>>`
}));
return [{ json: {
  content_id: ctx.content_id,
  suggestions: enriched,
  suggestion_count: enriched.length,
  state: 'WAITING_APPROVAL',
  published: false,
  draft_error: parse_error,
  note: 'dry-run。アフィリ挿入案のみ。★実リンク生成・自動埋め込み・公開はしない。人間が自分のアフィリID付きリンクをプレースホルダに差し込み、手動反映する。'
} }];

// QAゲート不通過。アフィリ提案生成をスキップ。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id,
  skipped: true,
  qa_status: i.qa_status,
  state: 'SKIPPED_NOT_PASS',
  published: false,
  note: 'qa_status が PASS ではないためアフィリ提案生成をスキップ。'
} }];
